import math


def principal_log(z):
    if z == 0:
        raise ValueError('Log 0 is undefined')
    return complex(math.log(abs(z)), math.atan2(z.imag, z.real))

import cmath
import math


def continuous_log(zs):
    out = []
    for z in zs:
        w = cmath.log(z)
        if out:
            while w.imag - out[-1].imag > math.pi:
                w -= 2j * math.pi
            while w.imag - out[-1].imag < -math.pi:
                w += 2j * math.pi
        out.append(w)
    return out
